import {toolBanner} from './tool-banner.mjs';
import {scenarios,themes,buildSlides,deckText,validateMaterial,validateDeck} from './presentation-model.mjs';
import {keys,list,write,projects,preferences,recordTask} from './state.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
let deck,ctx,root,busy=false,dirty=false,selected=0,tab='upload',preview=0,controller,serviceMode='ai',pptTier='basic';
let presentationEpoch=0;
export function disposePresentation(){presentationEpoch++;controller?.abort();controller=null;root=null;dirty=false;busy=false;}
const $=s=>root?.querySelector(s),defaultDeck=()=>({title:'',scenario:scenarios[0],projectId:'',degree:preferences().degree||'本科',minutes:10,pages:12,language:'中文',theme:'academic',author:'',school:'',advisor:'',material:'',fileName:'',prompt:'',slides:[]});
export const presentationHasWork=()=>!!root?.querySelector('.ppt-grid,.ppt-mode-layout')&&(dirty||busy);
export function presentationRouteGuard(){if(!root?.querySelector('.ppt-grid,.ppt-mode-layout'))return true;if(busy){ctx.notify('正在处理，请稍候。');return false;}if(dirty&&!window.confirm('有未保存的演示修改。离开会丢失这些修改，确定离开？'))return false;dirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(presentationHasWork()){e.preventDefault();e.returnValue='';}});
export function mountPresentation(context,draftId,projectId){disposePresentation();controller=new AbortController();ctx=context;const d=list(keys.drafts).find(d=>String(d.id)===String(draftId)&&d.tool==='ppt');deck=d?.presentation?structuredClone(d.presentation):defaultDeck();if(d){deck.id=d.id;deck.projectId=d.projectId||'';if(!d.presentation){deck.title=d.title;deck.material=d.text||'';deck.fileName='旧版演示提纲';}}else deck.projectId=projectId||'';const hash=String(location.hash||'');const mode=new URLSearchParams(hash.includes('?')?hash.split('?')[1]:'').get('mode');const savedMode=d?.presentation?.serviceMode;serviceMode=['ai','proposal','thesis'].includes(mode)?mode:['ai','proposal','thesis'].includes(savedMode)?savedMode:d?.presentation&&deck.scenario==='开题报告'?'proposal':d?.presentation&&deck.scenario==='毕业论文答辩'?'thesis':'ai';if(!d?.presentation||['ai','proposal','thesis'].includes(mode))deck.scenario=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':deck.scenario;pptTier=['basic','premium'].includes(d?.presentation?.pptTier)?d.presentation.pptTier:'basic';dirty=false;busy=false;selected=0;preview=0;tab=deck.material?'paste':'upload';root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});}
const pptModes=[['ai','AI PPT','通用汇报','从主题与要求整理演示结构','AI'],['proposal','开题 PPT','开题汇报','讲清研究问题、方法与技术路线','PLAN'],['thesis','毕业 PPT','毕业答辩','呈现研究发现、结论与贡献','DEFENSE']];
const quickLabels=['论文答辩','开题报告','职业规划','教学教案','工作计划','年终总结','内容策划','市场分析'];
function pptModeIcon(mode,size=24){const paths={ai:'M3 4h18v12H3zM8 21l4-5 4 5M8 11V8M12 11V6M16 11V9',proposal:'M4 3h16v18H4zM8 7h8M8 11h4M8 16h2l2-3 2 4 2-2',thesis:'m2 9 10-5 10 5-10 5zM6 11v6c4 3 8 3 12 0v-6M22 9v8'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[mode]||paths.ai}"/></svg>`;}
function pptJourney(){const steps=serviceMode==='ai'?['输入主题与材料','选择演示版式','逐页完善内容','导出可编辑 PPTX']:serviceMode==='proposal'?['导入开题报告','梳理研究计划','编辑路线与安排','导出开题汇报']:['导入论文材料','确认答辩结构','填写真实研究结果','导出答辩文稿'];return `<section class="ppt-journey" aria-label="${modeCopy[serviceMode].title}制作流程"><div><span class="ppt-section-kicker">YOUR PRESENTATION WORKFLOW</span><h2>${serviceMode==='ai'?'从一个主题，到一份清晰的演示':serviceMode==='proposal'?'让研究计划，拥有清晰的汇报结构':'让你的研究成果，被清楚地看见'}</h2></div><ol>${steps.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><b>${step}</b></li>`).join('')}</ol></section>`;}
function pptStartSettings(){return `<div class="ppt-start-settings">${field('title','演示标题',deck.title,120)}<label>目标页数<input type="number" data-field="pages" aria-label="目标页数" min="6" max="30" value="${deck.pages}"></label><label>预计汇报时长（分钟）<input type="number" data-field="minutes" aria-label="汇报时长" min="1" max="120" value="${deck.minutes}"></label></div>`;}
function selectOptions(values,value){return values.map(v=>`<option ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('');}
function field(id,label,value,max=100){return `<label>${label}<input data-field="${id}" aria-label="${label}" maxlength="${max}" value="${esc(value)}"></label>`;}
function pptServicePanel(){return `<section class="ppt-service-panel ppt-commercial" aria-label="PPT 创作服务"><div class="ppt-service-top"><div><span class="ppt-service-kicker">PRESENTATION STUDIO</span><h2>把研究内容，整理成一份能讲清楚的 PPT</h2><p>当前文稿可继续编辑、保存或导出；切换场景会保留已编辑的页面。</p></div><span class="hub-badge">本地结构模板 · PPTX 可导出</span></div><div class="ppt-service-modes" role="group" aria-label="演示文稿场景">${pptModes.map(([mode,title,tag,description])=>`<button type="button" class="ppt-entry-${mode} ${serviceMode===mode?'active':''}" data-ppt-mode="${mode}" aria-pressed="${serviceMode===mode}"><span class="ppt-entry-icon">${pptModeIcon(mode,22)}</span><span><b>${title}</b><small>${description}</small></span></button>`).join('')}</div><p class="ppt-service-note">${icon('shield',15)} 当前使用本地结构模板。正文、研究结果与演讲备注需要你依据真实材料补充。</p></section>`;}

const modeCopy={ai:{title:'AI PPT',banner:'输入汇报主题与要求，或导入参考材料，从可编辑的大纲开始制作。当前使用本地结构模板，AI 自动创作尚未开放。'},proposal:{title:'开题 PPT',banner:'导入开题报告，选择版式，再逐页整理研究问题、目标、方法与技术路线。材料在当前浏览器处理。'},thesis:{title:'毕业 PPT',banner:'导入论文，围绕研究问题、方法、结果与结论制作答辩演示。内容需依据真实材料填写，支持导出可编辑 PPTX。'}};
const modeTemplateNames={ai:['学术研究 · 清晰表达','研究汇报 · 沉稳蓝','项目展示 · 简洁版','科技研究 · 方法与发现','课堂汇报 · 重点呈现','研究计划 · 从问题出发'],proposal:['关于 XX 的现状、问题与对策研究','开题报告·研究计划','开题报告·技术路线','开题汇报·简洁版'],thesis:['关于 XX 的现状、问题与对策研究','毕业答辩·研究成果','毕业答辩·正式版','毕业论文·简洁模板']};
function modeNav(){return `<aside class="ppt-mode-rail" aria-label="选择 PPT 制作流程"><div class="ppt-mode-options" role="group" aria-label="PPT 创作场景">${pptModes.map(([mode,title,tag,description,kicker])=>`<button type="button" class="ppt-rail-item ppt-entry-${mode} ${serviceMode===mode?'active':''}" data-ppt-mode="${mode}" aria-pressed="${serviceMode===mode}"><span class="ppt-entry-icon">${pptModeIcon(mode,26)}</span><span class="ppt-entry-copy"><small>${kicker}</small><strong>${title}</strong><span>${description}</span></span><span class="ppt-entry-tag">${tag}</span></button>`).join('')}</div><div class="ppt-rail-bottom"><a class="ppt-rail-download" href="#assets?scope=local">${icon('folder',16)} 我的演示文稿 ${icon('arrow',14)}</a><span>${icon('shield',14)} 本地编辑 · 可导出 PPTX</span></div><details class="ppt-rail-faq"><summary>制作与导出说明</summary><div><article><h4>内容来自哪里？</h4><p>大纲来自本地结构模板，正文与备注由你根据真实材料编辑；当前不调用 AI。</p></article><article><h4>支持上传什么？</h4><p>可导入论文与开题报告的文本材料。自定义 PPTX 模板上传尚未开放。</p></article><article><h4>怎样继续编辑？</h4><p>保存文稿后可从“我的成果”继续。导出的 PPTX 可在 PowerPoint 或 WPS 中编辑。</p></article></div></details></aside>`;}

function modeTemplates(mode){return `<div class="ppt-mode-template-grid">${Object.entries(themes).map(([themeId,theme],i)=>`<button type="button" class="ppt-mode-template ${deck.theme===themeId?'selected':''}" data-ppt-template="${mode}-${i}" aria-pressed="${deck.theme===themeId}"><span class="ppt-template-art art-${i+1} ppt-theme-${themeId}"><small>PaperKnow · ${mode==='proposal'?'RESEARCH PROPOSAL':mode==='thesis'?'THESIS DEFENSE':'PRESENTATION'}</small><b>${mode==='proposal'?'研究计划与技术路线':mode==='thesis'?'研究发现与学术表达':'让研究内容，清晰呈现'}</b><i aria-hidden="true"></i><span>封面样式示意</span></span><span><b>${theme.name}</b><small>${deck.theme===themeId?'已选择':'选择版式'} ${deck.theme===themeId?'✓':'→'}</small></span></button>`).join('')}</div><p class="hub-footnote ppt-template-boundary">${Object.keys(themes).length} 种实际可导出的本地版式 · 封面为样式示意，正文内容需逐页填写。</p>`;}

function modeUpload(mode){const label=mode==='proposal'?'上传你的开题报告':'上传你的论文';return `<label class="ppt-mode-drop ${deck.material?'has-material':''}" id="ppt-drop">${icon('upload',34)}<b>${busy?'正在解析…':'点击或拖拽文件上传'}</b><span>DOCX / PDF / TXT · 最大 50MB</span><small>本地提取文本；扫描件和旧版 DOC 需先转换</small><input type="file" id="ppt-file" accept=".doc,.docx,.pdf,.txt" aria-label="${label}" ${busy?'disabled':''}></label><p id="ppt-material-state" class="ppt-mode-file-state ${deck.material?'has-material':'is-empty'}" aria-live="polite">${deck.material?`${esc(deck.fileName||'已上传文件')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未选择文件'}</p>`;}
function drawService(){const c=modeCopy[serviceMode];const ai=serviceMode==='ai';const label=serviceMode==='proposal'?'上传你的开题报告':'上传你的论文';const plan=serviceMode==='thesis'?`<div class="ppt-plan-row"><button class="ppt-plan ${pptTier==='basic'?'active':''}" data-ppt-tier="basic"><b>▣ 基础版</b><strong>本地模板可用</strong><span>答辩大纲、逐页编辑与 PPTX 导出</span></button><button class="ppt-plan ${pptTier==='premium'?'active':''}" data-ppt-tier="premium" disabled aria-disabled="true"><b>▣ 答辩资料包</b><strong>在线服务未开放</strong><span>自动生成答辩稿、资料清单与问答暂不可用</span></button></div>`:'';root.innerHTML=`${toolBanner('ppt',{extraClass:'detail-service-banner',description:'从研究材料到清晰汇报，选择场景后逐页制作演示文稿。',actions:`<a class="btn secondary" href="#assets?scope=local">我的演示文稿</a>`})}<div class="ppt-mode-layout ppt-grid ppt-commercial doc-tool-detail doc-tool-ppt" data-presentation-mode="${serviceMode}">${modeNav()}<div class="ppt-mode-main">${pptJourney()}<div class="ppt-mode-banner">${icon('speaker',16)}${c.banner}</div>${plan}<section class="ppt-mode-card">${ai?`<div class="ppt-compose-heading"><span class="ppt-compose-number">01</span><div><h2>描述你的演示需求</h2><p>说明汇报主题、听众与重点，先创建结构，再完善内容。</p></div><span class="ppt-compose-tag">本地结构模板</span></div><div class="ppt-ai-input"><label class="ppt-ai-field-label" for="ppt-brief">主题与制作要求</label><textarea id="ppt-brief" data-field="prompt" maxlength="80000" aria-label="PPT 需求" placeholder="请输入你的指令要求，说明汇报用途、听众、时长与重点内容">${esc(deck.prompt||'')}</textarea><div class="ppt-ai-tools"><button type="button" data-action="pick-file">${icon('file',14)}上传参考文档</button><button type="button" disabled title="联网搜索尚未开放">${icon('globe',14)}联网搜索 · 待开放</button><button type="button" disabled title="自动备注尚未开放，可在逐页编辑中填写">${icon('pen',14)}自动备注 · 待开放</button><span class="ppt-tool-meta">中文内容 · 手动编辑</span><span class="ppt-tool-meta">16:9 · 可编辑 PPTX</span></div><input class="ppt-inline-file" type="file" id="ppt-file" accept=".doc,.docx,.pdf,.txt" aria-label="上传参考文档"><label class="ppt-mode-author">作者：<input data-field="author" aria-label="作者" placeholder="请输入作者" value="${esc(deck.author||'')}"></label><p id="ppt-material-state" class="ppt-mode-file-state ${deck.material?'has-material':'is-empty'}" aria-live="polite">${deck.material?`${esc(deck.fileName||'已上传参考文档')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未上传参考文档'}</p></div>${pptStartSettings()}<div class="ppt-quick-presets"><span>快捷指令</span>${quickLabels.map((x,i)=>`<button data-ppt-quick="${i}">${x}</button>`).join('')}</div><h3 class="ppt-section-title"><span class="ppt-compose-number">02</span> 选择演示版式</h3><div class="ppt-filter-groups"><p>选择一种版式作为起点。以下为本地封面示意，生成大纲后可在编辑器切换实际导出版式。</p></div>${modeTemplates('ai')}<div class="ppt-mode-actions"><span class="ppt-action-note">${icon('file',15)} 创建可编辑结构，不自动编写研究结果。</span><button class="btn primary" data-action="generate">创建演示大纲</button><button class="btn secondary" data-action="custom-outline">自定义大纲</button></div>`:`<div class="ppt-compose-heading"><span class="ppt-compose-number">01</span><div><h2 class="ppt-mode-title">${label}</h2><p>${serviceMode==='proposal'?'从真实开题材料整理背景、研究目标与方法。':'从真实论文材料整理答辩结构与研究证据。'}</p></div><span class="ppt-compose-tag">本地提取正文</span></div>${modeUpload(serviceMode)}${pptStartSettings()}<div class="ppt-template-label"><span class="ppt-compose-number">02</span>选择演示版式</div>${modeTemplates(serviceMode)}<div class="ppt-mode-actions"><span class="ppt-action-note">${icon('file',15)} 创建可编辑结构，不自动编写研究结果。</span><button class="btn primary" data-action="generate">创建演示大纲</button></div>`}</section></div></div>`;bindDrop();}
function slidePreview(slide,small=false){const t=themes[deck.theme]||themes.academic;return `<div class="ppt-slide ${slide.layout==='cover'?'cover':''} ${small?'mini':''}" style="--ppt-accent:#${t.accent};--ppt-dark:#${t.dark}"><span>PaperKnow · ${esc(deck.scenario)}</span><h3>${esc(slide.title)}</h3><p>${esc(slide.body)}</p><small>${small?'':'16:9 · 文本预览'}</small></div>`;}
function drawEditor(){const slides=deck.slides,show=slides.length?slides[Math.min(preview,slides.length-1)]:{title:'论文题目示例',body:'毕业论文答辩\n作者 / 院校 / 导师',layout:'cover'};root.innerHTML=`${toolBanner('ppt',{extraClass:'detail-service-banner',description:'从论文到汇报，让研究表达更清晰。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('folder',16)} 我的演示文稿</a>`})}<div class="ppt-grid ppt-commercial ppt-editor-workspace doc-tool-detail doc-tool-ppt" data-presentation-mode="${serviceMode}"><section class="card ppt-card ppt-input-card doc-detail-panel"><header class="doc-detail-panel-head"><div><span class="doc-detail-eyebrow">01 · MATERIALS & STRUCTURE</span><h2>创建演示文稿 <span class="hub-badge">本地创作</span></h2><p>整理材料与汇报要求，逐页编辑你的研究内容。</p></div></header><div class="ppt-tabs" role="group" aria-label="汇报场景">${scenarios.map(s=>`<button data-scenario="${s}" aria-pressed="${deck.scenario===s}" class="${deck.scenario===s?'active':''}">${s}</button>`).join('')}</div><ol class="ppt-steps">${['导入材料','确认大纲','编辑演示','导出文件'].map((s,i)=>`<li class="${i===(slides.length?2:0)?'active':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol><b class="ppt-label">选择论文来源</b><div class="ppt-source-tabs">${[['upload','upload','上传论文'],['existing','folder','选择已有成果'],['paste','file','粘贴 / 核对材料']].map(([id,ico,n])=>`<button data-source="${id}" aria-pressed="${id===tab}" class="${id===tab?'active':''}">${icon(ico,16)}${n}</button>`).join('')}</div>${tab==='upload'?`<label class="ppt-drop" id="ppt-drop">${icon('upload',38)}<b>${busy?'正在解析…':'上传论文或报告'}</b><span>DOCX / PDF / TXT · 最大 50MB · PDF 最多 150 页</span><small>文本型 PDF；暂不支持扫描件 OCR。</small><input type="file" id="ppt-file" accept=".docx,.pdf,.txt" aria-label="上传论文或报告" ${busy?'disabled':''}></label>`:tab==='paste'?`<label class="ppt-label">材料正文<textarea data-field="material" aria-label="材料正文" maxlength="80000" rows="7" placeholder="粘贴需要整理的研究材料；不会自动上传。">${esc(deck.material)}</textarea></label>`:'<div class="ppt-drop"><b>从论文成果开始</b><button class="btn secondary" data-action="choose">选择已有成果</button><small>复制正文，原成果不变。</small></div>'}<p id="ppt-material-state" class="hub-footnote">${deck.material?`${esc(deck.fileName||'粘贴材料')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未导入材料'}</p><div class="ppt-fields"><label>所属项目<select data-field="projectId" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===deck.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${field('title','演示标题',deck.title,120)}</div><div class="ppt-fields four"><label>学段<select data-field="degree" aria-label="学段">${selectOptions(['专科','本科','硕士','博士','科研人员'],deck.degree)}</select></label><label>汇报时长（分钟）<input type="number" data-field="minutes" aria-label="汇报时长" min="1" max="120" value="${deck.minutes}"></label><label>目标页数<input type="number" data-field="pages" aria-label="目标页数" min="6" max="30" value="${deck.pages}"></label><label>演示语言<select data-field="language" aria-label="演示语言">${selectOptions(['中文','英文'],deck.language)}</select></label></div><details class="ppt-more"><summary>更多设置（作者、学校、导师）</summary><div class="ppt-fields">${field('author','作者',deck.author)}${field('school','学校 / 单位',deck.school)}${field('advisor','导师',deck.advisor)}</div></details><div class="ppt-actions"><button class="btn secondary" data-action="save">保存草稿</button><button class="btn primary" data-action="generate" ${busy?'disabled':''}>${slides.length?'重新创建大纲':'创建演示大纲'} ${icon('arrow',16)}</button></div><p class="hub-footnote">本地结构模板，未调用 AI；不会自动提炼或翻译材料。研究数据、结论与引用需依据实际材料填写。</p><p id="ppt-status" role="status" class="hub-footnote">${dirty?'有未保存修改':'当前浏览器保存，请及时导出备份。'}</p></section><aside class="ppt-preview-column"><section class="card ppt-card ppt-preview-card doc-detail-panel"><header class="doc-detail-panel-head"><div><span class="doc-detail-eyebrow">02 · PREVIEW & REVIEW</span><h2>模板与效果预览 <span class="hub-badge gray">${slides.length?'当前文稿':'模板示例'}</span></h2><p>核对当前页面与版式，再继续完善研究表达。</p></div></header><div class="ppt-tabs" role="group" aria-label="演示模板">${Object.entries(themes).map(([id,t])=>`<button data-theme="${id}" aria-pressed="${deck.theme===id}" class="${deck.theme===id?'active':''}">${t.name}</button>`).join('')}</div><div id="ppt-live-preview">${slidePreview(show)}</div><div class="ppt-thumbnails">${(slides.length?slides.slice(0,3):[{title:'论文题目示例',body:'答辩封面',layout:'cover'},{title:'研究方法',body:'填写实际研究设计'},{title:'结果分析',body:'填写真实研究证据'}]).map((s,i)=>`<button data-preview="${i}" aria-label="预览第 ${i+1} 页">${slidePreview(s,true)}</button>`).join('')}</div><p class="hub-footnote">16:9 · 文本可编辑 · 预览不保证与 PowerPoint 字体换行完全一致。</p></section><section class="card ppt-card"><h2>${slides.length?'演示大纲':'大纲结构预览'}</h2><div class="ppt-outline">${(slides.length?slides:[{title:'研究背景与问题'},{title:'文献回顾'},{title:'研究设计与方法'},{title:'研究结果与分析'},{title:'结论与研究贡献'},{title:'致谢与答辩'}]).map((s,i)=>`<button data-edit="${i}" ${slides.length?'':'disabled'}><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}${slides.length?icon('pen',14):''}</button>`).join('')}</div><p class="hub-footnote">${slides.length?'点击页面继续编辑；空缺内容不会被自动补造。':'示例结构，创建后可调整。'}</p></section></aside></div>${slides.length?editor():''}<section class="card ppt-card"><div class="hub-card-heading"><h2>最近演示文稿</h2><a href="#assets?scope=local">查看全部 →</a></div><div class="ppt-recents">${list(keys.drafts).filter(d=>d.tool==='ppt').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(d=>`<a href="#draft/${esc(d.id)}">${icon('chart',24)}<div><b>${esc(d.title)}</b><p>${d.presentation?.slides?.length||0} 页 · ${formatDate(d.updatedAt)}${d.presentation?'':' · 旧版提纲'}</p><span>继续编辑 →</span></div></a>`).join('')||'<p class="hub-footnote">尚无保存的演示文稿，导入材料后开始创建。</p>'}</div></section><div class="ppt-backup">${icon('shield',20)}<div><b>本地解析与编辑，不自动上传论文</b><p>可导出文本、可编辑 PPTX 和打印预览。本地文稿可从“我的成果”主动保存副本到账户；AI 自动创作尚未开放。</p></div></div>`;bindDrop();}
function draw(){return deck.slides.length?drawEditor():drawService();}
function editor(){const s=deck.slides[selected]||deck.slides[0];selected=deck.slides.indexOf(s);return `<section class="card ppt-card doc-tool-detail doc-tool-ppt ppt-page-editor" data-presentation-mode="${serviceMode}" id="ppt-editor"><div class="hub-card-heading"><h2>逐页编辑 <span class="hub-badge">第 ${selected+1} / ${deck.slides.length} 页</span></h2><div class="ppt-actions"><button class="btn secondary" data-action="add">添加页</button><button class="btn secondary" data-action="up" ${selected===0?'disabled':''}>上移</button><button class="btn secondary" data-action="down" ${selected===deck.slides.length-1?'disabled':''}>下移</button><button class="btn secondary" data-action="remove" ${deck.slides.length===1?'disabled':''}>移除页</button></div></div><div class="ppt-editor-grid"><div class="ppt-page-fields"><label class="ppt-label">页面标题<input data-slide="title" aria-label="页面标题" maxlength="120" value="${esc(s.title)}"></label><label class="ppt-label">页面正文<textarea data-slide="body" aria-label="页面正文" maxlength="1400" rows="6">${esc(s.body)}</textarea></label><label class="ppt-label">演讲备注<textarea data-slide="notes" aria-label="演讲备注" maxlength="3000" rows="3">${esc(s.notes)}</textarea></label></div><div class="ppt-source-reference"><details open><summary>参考材料（仅供核对）</summary><textarea readonly aria-label="参考材料" rows="10">${esc(deck.material)}</textarea></details><p class="hub-footnote">选取实际材料复制到左侧正文；每页建议保留 3–5 个要点。长文本在 PPTX 中可能缩小字号，请导出后核对。</p></div></div><div class="ppt-actions"><button class="btn primary" data-action="export">导出可编辑 PPTX</button><button class="btn secondary" data-action="print">打印预览 / 保存 PDF</button><button class="btn secondary" data-action="text">导出文本</button><button class="btn secondary" data-action="json">导出文稿备份</button><button class="btn secondary" data-action="save">保存文稿</button></div></section>`;}
function mark(){dirty=true;const status=$('#ppt-status');if(status)status.textContent='有未保存修改，请保存草稿或导出备份。';}
function inputChange(e){if(e.target.dataset.field){deck[e.target.dataset.field]=['pages','minutes'].includes(e.target.dataset.field)?Number(e.target.value):e.target.value;mark();if(e.target.dataset.field==='material')$('#ppt-material-state').textContent=`${deck.fileName||'粘贴材料'} · ${deck.material.length.toLocaleString('zh-CN')} 字符`;}if(e.target.dataset.slide){deck.slides[selected][e.target.dataset.slide]=e.target.value;mark();preview=selected;if($('#ppt-live-preview'))$('#ppt-live-preview').innerHTML=slidePreview(deck.slides[selected]);const entry=$(`[data-edit="${selected}"]`);if(entry)entry.innerHTML=`<span>${String(selected+1).padStart(2,'0')}</span>${esc(deck.slides[selected].title)}${icon('pen',14)}`;}if(e.target.id==='ppt-file')readFile(e.target.files[0]);}
function freeze(value){root?.querySelectorAll('input,textarea,select,button').forEach(el=>{if(value){el.dataset.pptDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.pptDisabled!==undefined){el.disabled=el.dataset.pptDisabled==='true';delete el.dataset.pptDisabled;}});}
function bindDrop(){const grid=root.querySelector('.ppt-grid');if(grid&&!root.querySelector('.ppt-mode-layout')&&!root.querySelector('.ppt-service-panel'))grid.insertAdjacentHTML('beforebegin',pptServicePanel());const drop=$('#ppt-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一份文件。');readFile(e.dataTransfer.files[0]);});}
async function readFile(file){const epoch=presentationEpoch;if(!file||busy)return;if(!/\.(doc|docx|pdf|txt)$/i.test(file.name)||file.size>50*1024*1024)return ctx.notify('请选择 50MB 以内的 DOC、DOCX、PDF 或 TXT。');if(deck.material&&!confirm('替换当前参考材料？已编辑的页面会保留，请重新核对。'))return;busy=true;freeze(true);const mounted=root;const state=$('#ppt-material-state');if(state)state.textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js');if(epoch!==presentationEpoch)return;const r=await extractFile(file);if(epoch!==presentationEpoch)return;const text=validateMaterial(r.text);if(!mounted.isConnected)return;deck.material=text;deck.fileName=file.name;if(!deck.title)deck.title=file.name.replace(/\.[^.]+$/,'');mark();tab='paste';ctx.notify(r.warnings.length?'文件已解析，部分页面有解析提示，请核对正文。':'已解析正文，请核对。');}catch(e){if(epoch===presentationEpoch)ctx.notify(e.message||'文件解析失败。');}finally{if(epoch===presentationEpoch){busy=false;if(mounted.isConnected)draw();}}}
export function savePresentationDraft(){if(!root)return false;save();return !dirty;}
function save(){if(!deck.title.trim())return ctx.notify('请填写演示标题。');try{const rows=list(keys.drafts),old=rows.find(d=>d.id===deck.id),now=new Date().toISOString(),id=deck.id||crypto.randomUUID();const saved={...old,id,title:deck.title.trim(),tool:'ppt',kind:deck.slides.length?'演示文稿':'演示草稿',stage:deck.slides.length?'presentation':'draft',projectId:deck.projectId,createdAt:old?.createdAt||now,updatedAt:now,text:deckText(deck),presentation:structuredClone({...deck,id,serviceMode,pptTier})};write(keys.drafts,old?rows.map(d=>d.id===id?saved:d):[saved,...rows]);deck.id=id;dirty=false;try{recordTask({id:'draft-'+id,title:deck.title,kind:'本地演示保存',status:'completed',projectId:deck.projectId,url:'#draft/'+id});}catch{}ctx.notify('文稿已保存到当前浏览器。');draw();}catch{ctx.notify('浏览器保存失败，请导出文稿备份。');}}
function choose(){const rows=list(keys.drafts).filter(d=>d.tool!=='ppt'&&(d.text?.trim()||d.html));ctx.modal('选择已有成果',`<p class="hub-footnote">复制已有正文；大纲与模板不代表真实论文。</p>${rows.map(d=>`<button class="ppt-existing" data-ppt-existing="${esc(d.id)}"><b>${esc(d.title)}</b><small>${esc(d.kind||'创作成果')}</small></button>`).join('')||'<p>暂无可导入成果。</p>'}`);document.querySelectorAll('[data-ppt-existing]').forEach(b=>b.addEventListener('click',()=>{const d=rows.find(d=>String(d.id)===b.dataset.pptExisting);if(deck.material&&!confirm('替换当前参考材料？'))return;let text=d.text||'';if(!text&&d.html){const div=document.createElement('div');div.innerHTML=d.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));text=div.textContent||'';}try{deck.material=validateMaterial(text);deck.title=d.title;deck.projectId=d.projectId||deck.projectId;deck.fileName='已有成果：'+d.title;tab='paste';mark();document.querySelector('#workspace-dialog').close();draw();}catch(e){ctx.notify(e.message);}}));}
async function actions(e){const epoch=presentationEpoch;const b=e.target.closest('button');if(!b)return;if(busy)return ctx.notify('正在处理，请稍候。');if(b.dataset.pptMode){serviceMode=b.dataset.pptMode;deck.scenario=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':scenarios[0];mark();draw();return;}if(b.dataset.pptTier){pptTier=b.dataset.pptTier;mark();draw();return;}if(b.dataset.pptTemplate){deck.theme=['academic','formal','focus'][Number(b.dataset.pptTemplate.split('-').pop())%3]||'academic';mark();root.querySelectorAll('[data-ppt-template]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});return;}if(b.dataset.pptQuick!==undefined){const labels=quickLabels;const label=labels[Number(b.dataset.pptQuick)];if(label==='开题报告')serviceMode='proposal',deck.scenario='开题报告';if(label==='论文答辩')serviceMode='thesis',deck.scenario='毕业论文答辩';if(!deck.title&&label)deck.title=label;if(serviceMode==='ai'&&!deck.prompt&&label)deck.prompt=`制作一份${label}演示文稿，按背景、核心内容、重点发现与总结组织结构。`;if(serviceMode!=='ai')deck.title=deck.title||modeCopy[serviceMode].title;mark();draw();return;}if(b.dataset.scenario){deck.scenario=b.dataset.scenario;mark();draw();return;}if(b.dataset.theme){deck.theme=b.dataset.theme;mark();draw();return;}if(b.dataset.source){tab=b.dataset.source;draw();if(tab==='existing')choose();return;}if(b.dataset.preview!==undefined){preview=Number(b.dataset.preview);draw();return;}if(b.dataset.edit!==undefined){selected=Number(b.dataset.edit);preview=selected;draw();$('#ppt-editor')?.scrollIntoView({block:'start',behavior:'smooth'});return;}try{switch(b.dataset.action){case 'pick-file':$('#ppt-file')?.click();break;case 'choose':choose();break;case 'custom-outline':serviceMode='ai';deck.scenario=deck.scenario||scenarios[0];deck.title=deck.title||'AI PPT';deck.material=deck.material||deck.prompt||'';if(!deck.material.trim())throw new Error('请先输入 PPT 主题或上传参考文档。');deck.pages=deck.pages||12;deck.slides=buildSlides(deck);selected=0;preview=0;mark();draw();ctx.notify('已创建自定义结构，请逐页补充真实材料。');break;case 'generate':if(serviceMode==='ai'&&!deck.material.trim()&&deck.prompt?.trim())deck.material=deck.prompt;if(!deck.title.trim())deck.title=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':'AI PPT';if(deck.slides.length&&!confirm('重新创建大纲将替换当前全部页面，请先保存或导出备份。确定继续？'))return;deck.slides=buildSlides(deck);selected=0;preview=0;mark();draw();ctx.notify('已创建结构大纲，请逐页补充真实材料。');break;case 'save':save();break;case 'add':if(deck.slides.length>=30)throw new Error('最多 30 页。');deck.slides.splice(selected+1,0,{id:crypto.randomUUID(),title:'新页面',body:'',notes:'',layout:'content'});selected++;preview=selected;mark();draw();break;case 'remove':if(!confirm('移除当前页？此操作不会修改已保存的文稿。'))return;deck.slides.splice(selected,1);selected=Math.max(0,selected-1);preview=selected;mark();draw();break;case 'up':case 'down':{const next=selected+(b.dataset.action==='up'?-1:1);if(next<0||next>=deck.slides.length)return;[deck.slides[selected],deck.slides[next]]=[deck.slides[next],deck.slides[selected]];selected=next;preview=selected;mark();draw();break;}case 'export':busy=true;freeze(true);try{const {exportPresentation}=await import('./assets/presentation-export.js');if(epoch!==presentationEpoch)return;await exportPresentation(deck);if(epoch!==presentationEpoch)return;ctx.notify('已导出 PPTX，请在 PowerPoint 中核对排版。');}finally{if(epoch===presentationEpoch){busy=false;freeze(false);}}break;case 'text':download(deck.title+'.txt',deckText(deck));break;case 'json':download((deck.title||'演示草稿')+'-PaperKnow.json',JSON.stringify(deck,null,2),'application/json');break;case 'print':validateDeck(deck);download(deck.title+'-打印预览.html',printHtml(),'text/html');ctx.notify('已下载打印预览，打开后选择打印并保存 PDF。');break;}}catch(error){if(epoch===presentationEpoch)ctx.notify(error.message||'操作失败，请重试。');}}
function printHtml(){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(deck.title)}</title><style>body{font-family:Arial,'Microsoft YaHei',sans-serif;margin:0;background:#eee}button{margin:20px;padding:12px}section{box-sizing:border-box;background:#fff;width:297mm;height:167mm;padding:22mm;page-break-after:always;border-left:4mm solid #${themes[deck.theme].accent}}h1{font-size:30pt;color:#${themes[deck.theme].dark}}p{font-size:20pt;white-space:pre-wrap;overflow-wrap:anywhere}@page{size:297mm 167mm;margin:0}@media print{button{display:none}body{background:white}}</style><button onclick="window.print()">打印 / 保存 PDF</button>${deck.slides.map(s=>`<section><small>PaperKnow · ${esc(deck.scenario)}</small><h1>${esc(s.title)}</h1><p>${esc(s.body)}</p></section>`).join('')}</html>`;}
